; Lifecycle work runs on edges, not on a slow screen timer.
function @visibility_trace($vt_tag : text)
	if !$standby_diagnostics
		return
	@diagnostics_begin(1, time)
	@diagnostics_word("VIS")
	@diagnostics_word($vt_tag)
	@diagnostics_number($display_sleep)
	@diagnostics_number($visibility_parked_sleep)
	@diagnostics_number($sqx_sw49_rotors__m)
	@diagnostics_number($sqx_sw49_ap__m)
	@diagnostics_finish()

function @visibility_clock_sync()
	if !$sqx_sw49_power__m
		; Do not prepare graphics or restart the solar receiver just to blank it.
		$sundial_lcd.draw_rect(0, 79, 150, 257, black, black)
		$sundial_key = "OFF"
		$shared_clock_power = 0
		$shared_clock_second = -1
		output_text("systems-dashboard", 18, "")
		output_text("systems-dashboard", 19, "")
		return
	$sundial_key = ""
	$shared_clock_second = -1
	@update_calendar_clock()
	@sundial_update()

function @visibility_scanners_quiet()
	@terrain_scan_release()
	@ore_scanner_quiet()
	@geology_quiet()
	@stopPivot()
	$ore_scanner_resuming = 1
	$scanner_options_settle = time + max(0.3, delta_time * 2)
	$ore_map_request = 0
	$ore_map_reply = 0

function @visibility_tick()
	if !$visibility_ready
		return
	; Anchored/OFF steady state needs no visibility recomputation or sensor reads.
	if $standby_mode != 0
		if ($visibility_power_seen == $sqx_sw49_power__m) and ($visibility_sleep_seen == $display_sleep) and ($visibility_boot_seen == $display_boot_done)
			return
	if $visibility_power_seen != $sqx_sw49_power__m
		$visibility_power_seen = $sqx_sw49_power__m
		@visibility_clock_sync()
		@visibility_trace("POWER")
	if $visibility_sleep_seen != $display_sleep
		$visibility_sleep_seen = $display_sleep
		if $display_sleep
			@visibility_scanners_quiet()
		else
			; Fresh packets after wake, not stale responses at old distances.
			$ore_scanner_resuming = 1
			$scanner_options_settle = time + max(0.3, delta_time * 2)
			$attitude_display_last_frame = ""
			$navigation_display_key = ""
			$systems_display_key = ""
		@visibility_trace("SLEEP-WAKE")
	$visibility_instruments = $sqx_sw49_power__m and (!$display_sleep) and $display_boot_done
	$visibility_scanners = $sqx_sw49_power__m and (!$display_sleep)
	; Sleep can suspend the inactive controller loop without claiming that an
	; unknown dock is anchored. Nav/radio position remains live on moving ships.
	var $visibility_idle = ($standby_mode == 0) and $sqx_sw49_power__m and $display_sleep and (!$sqx_sw49_rotors__m) and (!$sqx_sw49_ap__m) and (!$sqx_sw49_mine__m) and (!$docking_active) and (!$docking_acquiring)
	; Boolean expressions do not short-circuit in this runtime. Nest guards to
	; avoid polling anchor/port sensors when Sleep is not a candidate at all.
	if $visibility_idle
		if $sqx_sw49_land__m
			if !input_number("left-anchor", 0)
				$visibility_idle = 0
		if $sqx_sw49_dock__m
			if !input_number("ship-dock", 0)
				$visibility_idle = 0
	if $visibility_idle and (!$visibility_parked_sleep)
		; Logical switches and port/anchor state are NOT changed by Sleep.
		output_number("front-left-prop", 0, 0)
		output_number("front-right-prop", 0, 0)
		output_number("rear-left-prop", 0, 0)
		output_number("rear-right-prop", 0, 0)
		@latched_io(6,"front-left-prop-pwr",0,0)
		@latched_io(7,"front-right-prop-pwr",0,0)
		@latched_io(8,"rear-left-prop-pwr",0,0)
		@latched_io(9,"rear-right-prop-pwr",0,0)
	var $visibility_idle_changed = $visibility_parked_sleep != $visibility_idle
	$visibility_parked_sleep = $visibility_idle
	if $visibility_idle_changed
		@visibility_trace("IDLE-CONTROL")
	$visibility_boot_seen = $display_boot_done

function @visibility_init()
	$visibility_ready = 1
	@visibility_tick()

; OFF is an event-only power panel. All other periodic entry points return.
var $strict_off_done=0

function @strict_off_enter()
	if $mission_mode or $ore_ui_pending
		@mission_cancel("POWER OFF")
	if $strict_off_done
		return
	$ui_secure_last=-1
	$ui_secure_until=0
	$ui_secure_pending=0
	@seal_clear()
	@standby_enter(1)
	@dev_gear_service()
	@ts_flush()
	@wx_service()
	@fleet_shutdown()
	@guide_service_clear()
	@hud_subscription_release()
	@lights_update_lamps()
	@lights_poweroff()
	@attitude_display_poweroff()
	@navigation_display_poweroff()
	@systems_display_poweroff()
	@power_display_poweroff()
	@beacon_display_off()
	@access_render()
	@interior_door_render()
	@mining_display_render()
	@throttle_display_render()
	@beacon_title_title_update()
	@visibility_tick()
	@display_compose()
	@display_controls_draw()
	; Prepare cached UI once, then leave ONLY the SYSTEMS/PWR panel visible.
	@du_strip_prepare()
	$du_strip_lcd.blank(black)
	$cockpit_controls_actions.blank(black)
	$power_display_lcd.blank(black)
	$light_controls_lights.blank(black)
	$sundial_lcd.blank(black)
	$beacon_lcd.blank(black)
	$throttle_display_lcd.blank(black)
	$mining_display_lcd.blank(black)
	screen_copy($du_strip_frame,$du_strip_lcd,0,0,0,0,150,120)
	$cockpit_controls_lcd=$du_strip_lcd
	@cockpit_controls_button(0,12,20,60,44,"PWR",0,0)
	; Other SYSTEMS buttons remain visible but have no active input path.
	@du_simple_button(14,81,20,60,"SOUND",17,gray)
	@du_simple_button(2,12,70,60,"PARK",20,gray)
	@du_simple_button(15,81,70,60,"BCN TX",18,gray)
	$standby_live_enabled=0
	$standby_work_enabled=0
	$standby_visual_enabled=0
	$standby_ui_until=0
	$strict_off_done=1

function @strict_off_exit()
	$strict_off_done=0
	$standby_visual_enabled=1
	$du_strip_global="!"
	$du_strip_context="!"
	$du_strip_keys.fill(16,"!")
	screen_copy($du_strip_frame,$du_strip_lcd,0,0,0,0,300,120)
	screen_copy($du_strip_frame2,$cockpit_controls_actions,0,0,0,0,300,120)

function @strict_power_step() : number
	if !$sqx_sw49_power__m
		if !$strict_off_done
			@strict_off_enter()
		return 0
	if $strict_off_done
		@strict_off_exit()
	@standby_step()
	return 1

function @strict_power_touch($x:number,$y:number)
	if ($x>=12) and ($x<72) and ($y>=20) and ($y<64)
		@switches_action(0)
		@strict_power_step()

var $cc_busy = 0
var $cc_round = 0
var $cc_result = ""

function @cc_begin($cc_counter : number, $cc_nonce : text)
	$cr_state.clear()
	$cr_state.append(1634760805,857760878,2036477234,1797285236)
	foreach $cr_key ($cc_i,$cc_v)
		$cr_state.append($cc_v)
	$cr_state.append($cc_counter)
	repeat 3 ($cc_i)
		$cr_state.append(@cr_le_word(substring($cc_nonce,$cc_i * 8,8)))
	$cr_original.from($cr_state)
	$cc_round = 0
	$cc_busy = 1
	$cc_result = ""

function @cc_step()
	if !$cc_busy
		return
	repeat 2 ($cc_slice)
		@cr_qr(0,4,8,12)
		@cr_qr(1,5,9,13)
		@cr_qr(2,6,10,14)
		@cr_qr(3,7,11,15)
		@cr_qr(0,5,10,15)
		@cr_qr(1,6,11,12)
		@cr_qr(2,7,8,13)
		@cr_qr(3,4,9,14)
		$cc_round += 1
	if $cc_round < 10
		return
	repeat 16 ($cc_i)
		$cc_result &= @cr_word_hex(mod($cr_state.$cc_i + $cr_original.$cc_i,4294967296))
	$cc_busy = 0

; Cosmetic tutorial link and the previously unowned cockpit LV relay.
; No tutorial packet can invoke controls, PIDs, navigation, mining or door actions.
; Standby centrally owns service/charging relays; manual CPU feed stays untouched.
var $guide_service_page = -1
var $guide_service_flash = 0
var $guide_service_revision = 0
var $guide_service_expire = 0
var $guide_service_identity = 0
var $guide_service_session = ""
var $guide_service_radio_ready = 0
var $guide_service_sequence = -1
var $guide_service_ink : number
var $service_relay_last = -1

function @guide_service_field($guide_packet : text, $guide_field : text) : text
	foreach $guide_packet ($guide_key, $guide_value)
		if $guide_key == $guide_field
			return $guide_value
	return ""

function @guide_service_clear()
	if ($guide_service_page != -1) or $guide_service_flash
		$guide_service_page = -1
		$guide_service_flash = 0
		$guide_service_revision += 1
	$guide_service_expire = 0

function @guide_service_active($guide_button : number) : number
	if (!$guide_service_flash) or (time >= $guide_service_expire)
		return 0
	if $guide_service_page == 2
		return $guide_button == 1
	if $guide_service_page == 8
		return ($guide_button == 12) or ($guide_button == 16)
	if $guide_service_page == 9
		return ($guide_button >= 8) and ($guide_button <= 11)
	if $guide_service_page == 10
		return ($guide_button >= 13) and ($guide_button <= 15)
	if $guide_service_page == 11
		return ($guide_button == 3) or ($guide_button == 4)
	if $guide_service_page == 12
		return $guide_button == 13
	if $guide_service_page == 13
		return ($guide_button >= 5) and ($guide_button <= 7)
	if $guide_service_page == 14
		return ($guide_button == 2) or ($guide_button == 4)
	return 0

function @guide_service_border($guide_canvas : screen, $guide_x : number, $guide_y : number, $guide_w : number, $guide_h : number, $guide_button : number)
	if !@guide_service_active($guide_button)
		return
	; Outside-only bright border: preserve all labels, icons and ON/OFF colors.
	repeat 2 ($guide_stroke)
		$guide_canvas.draw_rect($guide_x - $guide_stroke - 1, $guide_y - $guide_stroke - 1, $guide_x + $guide_w + $guide_stroke + 1, $guide_y + $guide_h + $guide_stroke + 1, $guide_service_ink)

function @service_relay_apply()
	; Relay ownership is centralized in the early standby supervisor.

function @guide_service_boot()
	$guide_service_ink = color(255, 235, 70)
	@service_relay_apply()

function @guide_service_sample()
	@service_relay_apply()
	var $guide_seated = input_number("flight-seat", 0)
	if ($guide_seated == 0) or ($guide_seated == 1) or (device_type("guide-link") != "Beacon")
		@guide_service_clear()
		if $guide_service_identity != 0
			output_text("guide-link", 0, "")
		$guide_service_identity = 0
		return
	if !$guide_service_radio_ready
		; Public, cosmetic-only frequencies: no private beacon/command reuse.
		output_text("guide-link", 1, "BADGER-GUIDE-UI-OUT")
		output_text("guide-link", 2, "BADGER-GUIDE-UI-IN")
		$guide_service_radio_ready = 1
	if $guide_service_identity != $guide_seated
		$guide_service_identity = $guide_seated
		; Independent correlation nonce, not the seat token or an authentication key.
		$guide_service_session = text("{0}-{0}", time * 1000, tick)
		output_text("guide-link", 0, ".g{1}.s{" & $guide_service_session & "}")
		$guide_service_sequence = -1
		@guide_service_clear()
	if $guide_service_expire and (time >= $guide_service_expire)
		@guide_service_clear()
	if !input_number("guide-link", 5)
		return
	var $guide_distance = input_number("guide-link", 1)
	if ($guide_distance < 0) or ($guide_distance > 10)
		return
	var $guide_reply = input_text("guide-link", 0)
	if (size($guide_reply) > 160) or (@guide_service_field($guide_reply, "g") != "1") or (@guide_service_field($guide_reply, "s") != $guide_service_session)
		return
	var $guide_page_text = @guide_service_field($guide_reply, "p")
	var $guide_flash_text = @guide_service_field($guide_reply, "f")
	var $guide_sequence_text = @guide_service_field($guide_reply, "q")
	if !isnumeric($guide_page_text) or !isnumeric($guide_flash_text) or !isnumeric($guide_sequence_text)
		return
	var $guide_new_page = $guide_page_text:number
	var $guide_new_flash = $guide_flash_text:number
	var $guide_new_sequence = $guide_sequence_text:number
	if ($guide_new_page < -1) or ($guide_new_page > 14) or ($guide_new_page != floor($guide_new_page)) or (($guide_new_flash != 0) and ($guide_new_flash != 1))
		return
	if ($guide_new_sequence < 0) or ($guide_new_sequence != floor($guide_new_sequence)) or ($guide_new_sequence == $guide_service_sequence)
		; A latched old radio packet cannot keep an abandoned highlight alive.
		return
	$guide_service_sequence = $guide_new_sequence
	if ($guide_new_page != $guide_service_page) or ($guide_new_flash != $guide_service_flash)
		$guide_service_page = $guide_new_page
		$guide_service_flash = $guide_new_flash
		$guide_service_revision += 1
	$guide_service_expire = time + 1.25

